@startuml

class School {
  + Name : string
}

class Person {
  + FirstName : string
  + LastName : string
}

class Teacher extends Person {
  + EmailAddress : string
}

class Student extends Person {
}

class TeachingRelationship {
  + Hours : int
}

class ClassGroup {
  + Name : string
}

class Classroom {
  + Name : string
  + Capacity : int
}

class Gym {
  + Name : string
  + Size : float
}

class Room {
}

Room <|-- Classroom
Room <|-- Gym

School "1" -- "1" Teacher : Principal
School "1" -- "*" Teacher : employs
School "1" -- "1" Student : attends
School "1" -- "*" Room : consists of
School "0..3" -- "1" Teacher : teaches
TeachingRelationship "1" -- "1" Teacher
TeachingRelationship "1" -- "1" School

Student "1" -- "1" ClassGroup : belongs to
ClassGroup "1" -- "1" Classroom : assigned to
ClassGroup "10..31" -- "1" Student : contains

@enduml

